### **Q2: Write a program to read two distances in feet and inches and add them using structure.**

```c
#include <stdio.h>

struct Distance {
    int feet;
    int inches;
};

int main() {
    struct Distance d1, d2, sum;

    printf("Enter first distance (feet and inches): ");
    scanf("%d %d", &d1.feet, &d1.inches);

    printf("Enter second distance (feet and inches): ");
    scanf("%d %d", &d2.feet, &d2.inches);

    sum.inches = d1.inches + d2.inches;
    sum.feet = d1.feet + d2.feet + (sum.inches / 12);
    sum.inches = sum.inches % 12;

    printf("\nTotal Distance: %d feet %d inches\n", sum.feet, sum.inches);

    return 0;
}
```

